#include <stdio.h>

int main() {
    int A = 2000, mem_2000 = 3000;     /* 直接寻址地址码；一次间接指向的内容 */
    int R1 = 4000;                     /* 寄存器间接：寄存器里存的是地址 */
    int BR = 5000, dispB = 200;        /* 基址寄存器与位移 */
    int IX = 50, dispI = 1000;         /* 变址寄存器与位移 */
    int PC = 8000, dispR = -4;         /* 相对寻址：PC 已指向下一条指令 */

    printf("直接寻址   EA = %d\n", A);
    printf("一次间接   EA = M[%d] = %d\n", A, mem_2000);
    printf("寄存器间接 EA = (R1) = %d\n", R1);
    printf("基址寻址   EA = BR + disp = %d + %d = %d\n", BR, dispB, BR + dispB);
    printf("变址寻址   EA = IX + disp = %d + %d = %d\n", IX, dispI, IX + dispI);
    printf("相对寻址   EA = PC + disp = %d + %d = %d\n", PC, dispR, PC + dispR);
    return 0;
}
